-- Canonical configurator discount values are stored as decimal fractions
-- (for example 0.30 = 30%). Normalise them to display percentages.
create or replace function public.crm_dealer_sales_dashboard(
  p_from date default null, p_to date default null, p_countries text[] default null,
  p_sellers text[] default null, p_dealer_numbers text[] default null,
  p_customers text[] default null, p_machines text[] default null,
  p_partner_types text[] default null, p_display_currency text default 'both',
  p_limit integer default 100, p_offset integer default 0, p_view_as_user_id uuid default null
) returns jsonb language plpgsql stable security definer set search_path = public, auth as $function$
declare
  v_actor public.app_users%rowtype; v_subject public.app_users%rowtype; v_role text;
  v_is_backend boolean := false; v_is_external boolean := false;
  v_display_currency text := upper(coalesce(nullif(trim(p_display_currency), ''), 'BOTH'));
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 200); v_offset integer := greatest(coalesce(p_offset, 0), 0); v_result jsonb;
begin
  select * into v_actor from public.app_users au where coalesce(au.approved, false) and coalesce(au.is_active, false) and (au.auth_user_id = auth.uid() or lower(trim(au.email)) = lower(trim(coalesce(auth.jwt() ->> 'email', '')))) order by (au.auth_user_id = auth.uid()) desc limit 1;
  if not found then raise exception 'Authenticated portal user is required' using errcode = '42501'; end if;
  v_is_backend := coalesce(v_actor.portal_role::text, v_actor.role) in ('timan_backend', 'timan_service');
  if p_view_as_user_id is not null and p_view_as_user_id <> v_actor.id then
    if not v_is_backend then raise exception 'Only Timan Backend may use a view-as dashboard scope' using errcode = '42501'; end if;
    select * into v_subject from public.app_users au where au.id = p_view_as_user_id and coalesce(au.approved, false) and coalesce(au.is_active, false);
    if not found then raise exception 'Requested view-as user is not active' using errcode = '42501'; end if;
  else v_subject := v_actor; end if;
  v_role := coalesce(v_subject.portal_role::text, v_subject.role, ''); v_is_external := v_role in ('timan_importer', 'timan_dealer', 'timan_service_partner', 'dealer_customer', 'dealer_user');
  if v_display_currency not in ('DKK', 'EUR', 'BOTH') then raise exception 'Display currency must be DKK, EUR or BOTH' using errcode = '22023'; end if;
  with recursive subject_account as (select da.id, da.account_number from public.dealer_accounts da where nullif(v_subject.dealer_number, '') is not null and da.account_number = v_subject.dealer_number limit 1),
  seller_accounts as (select da.id, da.account_number from public.dealer_accounts da where v_role = 'timan_seller' and (da.assigned_seller_id = v_subject.id or lower(coalesce(da.assigned_seller_email, '')) = lower(coalesce(v_subject.email, '')) or upper(coalesce(da.assigned_seller_initials, '')) = upper(coalesce(v_subject.initials, '')))),
  account_scope as (select id, account_number from seller_accounts union select da.id, da.account_number from public.dealer_accounts da join seller_accounts parent on parent.account_number = da.parent_account_number union select id, account_number from subject_account union select da.id, da.account_number from public.dealer_accounts da join subject_account own on v_is_external and da.parent_account_number = own.account_number union select target.id, target.account_number from public.partner_account_relations par join subject_account own on own.id = par.source_account_id join public.dealer_accounts target on target.id = par.target_account_id where v_role = 'timan_service_partner' and par.active = true),
  scoped_configurations as (select c.id,c.quote_number,c.order_number,c.customer_name,c.customer_company,c.seller_initials,c.seller_name,c.assigned_seller_id,c.dealer_number,c.dealer_name,c.dealer_account_id,c.currency,c.subtotal,c.total_price,c.state_json,c.quote_sent_at,c.submitted_at,c.order_sent_at,c.created_at,da.company_name as dealer_company_name,da.country as dealer_country,da.customer_type_label,da.customer_type,da.dealer_type,case when c.submitted_at is not null or c.order_sent_at is not null then 'order' when c.quote_sent_at is not null then 'quote' else 'draft' end as record_kind from public.configurations c left join public.dealer_accounts da on da.id=c.dealer_account_id or (c.dealer_account_id is null and da.account_number=c.dealer_number) where coalesce(c.case_status,'') <> 'deleted' and ((v_role in ('timan_backend','timan_service')) or (v_role='timan_seller' and (c.assigned_seller_id=v_subject.id or c.dealer_account_id in (select id from account_scope) or c.dealer_number in (select account_number from account_scope))) or (v_is_external and (c.dealer_account_id in (select id from account_scope) or c.dealer_number in (select account_number from account_scope))))),
  expanded as (select sc.*,coalesce(nullif(upper(sc.currency),''),case when coalesce(sc.state_json->>'language','da')='da' then 'DKK' else 'EUR' end) as source_currency,coalesce(sc.subtotal,0)::numeric as list_price,coalesce(sc.total_price,0)::numeric as net_value,case when abs(coalesce(nullif(sc.state_json->>'baseDiscountPct','')::numeric,0)) <= 1 then coalesce(nullif(sc.state_json->>'baseDiscountPct','')::numeric,0)*100 else coalesce(nullif(sc.state_json->>'baseDiscountPct','')::numeric,0) end as standard_discount_pct,case when abs(coalesce(nullif(sc.state_json->>'manualDealerDiscountPct','')::numeric,0)) <= 1 then coalesce(nullif(sc.state_json->>'manualDealerDiscountPct','')::numeric,0)*100 else coalesce(nullif(sc.state_json->>'manualDealerDiscountPct','')::numeric,0) end as extra_discount_pct,coalesce(sc.order_sent_at,sc.submitted_at,sc.quote_sent_at,sc.created_at)::date as activity_date,coalesce(nullif(sc.dealer_company_name,''),nullif(sc.dealer_name,''),'—') as dealer,coalesce(nullif(sc.dealer_country,''),'—') as country,coalesce(nullif(sc.customer_company,''),nullif(sc.customer_name,''),'—') as customer,coalesce(nullif(sc.seller_initials,''),nullif(sc.seller_name,''),'—') as timan_seller,case when lower(concat_ws(' ',sc.customer_type_label,sc.customer_type,sc.dealer_type)) like '%import%' then 'Importør' when lower(concat_ws(' ',sc.customer_type_label,sc.customer_type,sc.dealer_type)) like '%service%' then 'Servicepartner' when lower(concat_ws(' ',sc.customer_type_label,sc.customer_type,sc.dealer_type)) like '%forhandlerkunde%' then 'Forhandlerkunde' else 'Forhandler' end as partner_type,coalesce(sc.state_json->'machineConfigs','[]'::jsonb) as machine_configs from scoped_configurations sc),
  rows as (select e.*,greatest(e.list_price-e.net_value,0)::numeric as discount_value,case when e.list_price>0 then round(((e.list_price-e.net_value)/e.list_price)*100,2) else null end as total_discount_pct,case when e.source_currency='EUR' then e.net_value*7.46 else e.net_value end as net_dkk,case when e.source_currency='EUR' then e.list_price*7.46 else e.list_price end as list_dkk,coalesce((select sum(greatest(coalesce(nullif(machine->>'qty','')::integer,0),0)) from jsonb_array_elements(e.machine_configs) machine),0)::integer as machine_count,coalesce((select string_agg(distinct nullif(machine->>'type',''),', ' order by nullif(machine->>'type','')) from jsonb_array_elements(e.machine_configs) machine),'—') as machine from expanded e where e.record_kind in ('order','quote') and (p_from is null or e.activity_date>=p_from) and (p_to is null or e.activity_date<=p_to) and (coalesce(array_length(p_countries,1),0)=0 or e.country=any(p_countries)) and (coalesce(array_length(p_sellers,1),0)=0 or e.timan_seller=any(p_sellers)) and (coalesce(array_length(p_dealer_numbers,1),0)=0 or e.dealer_number=any(p_dealer_numbers)) and (coalesce(array_length(p_customers,1),0)=0 or e.customer=any(p_customers)) and (coalesce(array_length(p_partner_types,1),0)=0 or e.partner_type=any(p_partner_types)) and (coalesce(array_length(p_machines,1),0)=0 or exists(select 1 from jsonb_array_elements(e.machine_configs) machine where machine->>'type'=any(p_machines)))),
  order_rows as (select * from rows where record_kind='order'), display_rows as (select *,case when v_display_currency='EUR' then net_dkk/7.46 else net_dkk end as display_net,case when v_display_currency='EUR' then list_dkk/7.46 else list_dkk end as display_list from order_rows),
  partner_sales_label as (select case when not v_is_external then null when (select count(*) from public.dealer_contacts dc join subject_account own on own.id=dc.dealer_account_id where lower(coalesce(dc.contact_area,'')) in ('sales','salg') or lower(coalesce(dc.role_title,'')) like '%sales%')=1 then (select coalesce(nullif(dc.name,''),'Info mangler') from public.dealer_contacts dc join subject_account own on own.id=dc.dealer_account_id where lower(coalesce(dc.contact_area,'')) in ('sales','salg') or lower(coalesce(dc.role_title,'')) like '%sales%' limit 1) else 'Info mangler' end as label)
  select jsonb_build_object('scope',jsonb_build_object('user_id',v_subject.id,'role',v_role,'is_backend',v_role in ('timan_backend','timan_service'),'is_external',v_is_external,'display_currency',v_display_currency),'summary',jsonb_build_object('revenue',coalesce((select sum(display_net) from display_rows),0),'order_count',(select count(*) from display_rows),'machine_count',coalesce((select sum(machine_count) from display_rows),0),'average_discount_pct',coalesce((select avg(total_discount_pct) from display_rows),0),'extra_discount_value',null,'payment_delivery_discount_value',null,'top_country',coalesce((select country from display_rows group by country order by sum(display_net) desc,country limit 1),'Ikke tilgængeligt'),'top_dealer',coalesce((select dealer from display_rows group by dealer order by sum(display_net) desc,dealer limit 1),'Ikke tilgængeligt'),'quote_count',(select count(*) from rows where record_kind='quote')),'charts',jsonb_build_object('revenue_over_time',coalesce((select jsonb_agg(jsonb_build_object('name',to_char(activity_date,'YYYY-MM'),'value',value) order by activity_date) from (select activity_date,sum(display_net) as value from display_rows group by activity_date)x),'[]'::jsonb),'revenue_by_year',coalesce((select jsonb_agg(jsonb_build_object('name',year,'value',value) order by year) from (select extract(year from activity_date)::text as year,sum(display_net) as value from display_rows group by extract(year from activity_date)::text)x),'[]'::jsonb),'top_dealers',coalesce((select jsonb_agg(jsonb_build_object('name',dealer,'value',value) order by value desc,dealer) from(select dealer,sum(display_net)as value from display_rows group by dealer order by value desc,dealer limit 10)x),'[]'::jsonb),'by_country',coalesce((select jsonb_agg(jsonb_build_object('name',country,'value',value) order by value desc,country) from(select country,sum(display_net)as value from display_rows group by country)x),'[]'::jsonb),'by_seller',coalesce((select jsonb_agg(jsonb_build_object('name',case when v_is_external then(select label from partner_sales_label)else timan_seller end,'value',value)order by value desc)from(select timan_seller,sum(display_net)as value from display_rows group by timan_seller)x),'[]'::jsonb),'machine_volume',coalesce((select jsonb_agg(jsonb_build_object('name',machine,'value',value)order by value desc,machine)from(select machine,sum(machine_count)as value from display_rows group by machine)x),'[]'::jsonb),'machine_value',coalesce((select jsonb_agg(jsonb_build_object('name',machine,'value',value)order by value desc,machine)from(select machine,sum(display_net)as value from display_rows group by machine)x),'[]'::jsonb),'dk_vs_de',coalesce((select jsonb_agg(jsonb_build_object('name',country,'value',value)order by country)from(select country,sum(display_net)as value from display_rows where country in('Danmark','Tyskland')group by country)x),'[]'::jsonb),'discount_by_machine',coalesce((select jsonb_agg(jsonb_build_object('name',machine,'standard',standard,'extra',extra,'payment',null)order by machine)from(select machine,avg(standard_discount_pct)as standard,avg(extra_discount_pct)as extra from display_rows group by machine)x),'[]'::jsonb),'discount_over_time',coalesce((select jsonb_agg(jsonb_build_object('name',year,'standard',standard,'extra',extra,'total',total)order by year)from(select extract(year from activity_date)::text as year,avg(standard_discount_pct)as standard,avg(extra_discount_pct)as extra,avg(total_discount_pct)as total from display_rows group by extract(year from activity_date)::text)x),'[]'::jsonb),'discount_value_by_year',coalesce((select jsonb_agg(jsonb_build_object('name',year,'standard',standard,'extra',extra,'payment',null)order by year)from(select extract(year from activity_date)::text as year,sum(case when v_display_currency='EUR'then list_dkk/7.46*standard_discount_pct/100 else list_dkk*standard_discount_pct/100 end)as standard,null::numeric as extra from display_rows group by extract(year from activity_date)::text)x),'[]'::jsonb)),'filters',jsonb_build_object('countries',coalesce((select jsonb_agg(distinct country order by country)from rows),'[]'::jsonb),'sellers',coalesce((select jsonb_agg(distinct timan_seller order by timan_seller)from rows),'[]'::jsonb),'dealers',coalesce((select jsonb_agg(jsonb_build_object('number',dealer_number,'name',dealer)order by dealer)from(select distinct dealer_number,dealer from rows)x),'[]'::jsonb),'customers',coalesce((select jsonb_agg(distinct customer order by customer)from rows),'[]'::jsonb),'machines',coalesce((select jsonb_agg(distinct machine order by machine)from rows where machine<>'—'),'[]'::jsonb),'partner_types',coalesce((select jsonb_agg(distinct partner_type order by partner_type)from rows),'[]'::jsonb)),'detail',jsonb_build_object('total_count',(select count(*)from rows),'limit',v_limit,'offset',v_offset,'rows',coalesce((select jsonb_agg(jsonb_build_object('id',id,'record_kind',record_kind,'order_number',order_number,'quote_number',quote_number,'date',activity_date,'seller',timan_seller,'country',country,'dealer',dealer,'dealer_number',dealer_number,'customer',customer,'machine',machine,'machine_count',machine_count,'list_price',list_price,'net_value',net_value,'currency',source_currency,'standard_discount_pct',standard_discount_pct,'extra_discount_pct',extra_discount_pct,'payment_delivery_discount_pct',null,'total_discount_pct',total_discount_pct,'discount_value',discount_value)order by activity_date desc,id)from(select*from rows order by activity_date desc,id limit v_limit offset v_offset)paged),'[]'::jsonb))) into v_result;
  return v_result;
end;
$function$;

revoke all on function public.crm_dealer_sales_dashboard(date,date,text[],text[],text[],text[],text[],text[],text,integer,integer,uuid) from public, anon;
grant execute on function public.crm_dealer_sales_dashboard(date,date,text[],text[],text[],text[],text[],text[],text,integer,integer,uuid) to authenticated, service_role;
